# 5.6 — Sysmon: đọc Event ID 1, 3, 7, 8, 10, 11, 12–14, 22 trên mẫu công khai (log kênh Microsoft-Windows-Sysmon/Operational).
# mau/sysmon.evtx (một máy Win10 có cấu hình sysmon thật, 358 sự kiện) + sm/ = 13 tệp EVTX-ATTACK-SAMPLES/EVTX-to-MITRE-Attack (tải: mau/tai-mau-ch5.ps1.txt).
@ps Get-WinEventMau (Get-ChildItem mau/sysmon.evtx, sm/*.evtx).FullName | Where-Object ProviderName -eq 'Microsoft-Windows-Sysmon' | Group-Object Id | Sort-Object { [int]$_.Name } | Format-Table @{n='Id'; e={$_.Name}}, Count -AutoSize
@ps Get-WinEventMau -FilterHashtable @{ Path = 'mau/sysmon.evtx'; Id = 16 } | ForEach-Object { ([xml]$_.ToXml()).Event.EventData.Data | Format-Table Name, '#text' -AutoSize }
@ps Get-WinEventMau -FilterHashtable @{ Path = 'mau/sysmon.evtx'; Id = 1 } -Oldest -MaxEvents 1 | ForEach-Object { ([xml]$_.ToXml()).Event.EventData.Data | Format-Table Name, '#text' -AutoSize -Wrap }
@ps Get-WinEventMau -FilterHashtable @{ Path = 'sm/webshell-1-10.evtx'; Id = 1 } -Oldest | ForEach-Object { $d = @{}; ([xml]$_.ToXml()).Event.EventData.Data | ForEach-Object { $d[$_.Name] = $_.'#text' }; '{0}  {1} -> {2}   {3}   [{4}]' -f $d.UtcTime.Substring(11), ($d.ParentImage -split '\\')[-1], ($d.Image -split '\\')[-1], $d.CommandLine, $d.User }
@ps Get-WinEventMau sm/rotten-potato-1-8-3.evtx -Oldest | ForEach-Object { $d = @{}; ([xml]$_.ToXml()).Event.EventData.Data | ForEach-Object { $d[$_.Name] = $_.'#text' }; '{0}  {1,-2} {2}' -f $d.UtcTime.Substring(11, 8), $_.Id, $(switch ($_.Id) { 1 { 'tạo tiến trình  ' + ($d.ParentImage -split '\\')[-1] + ' -> ' + ($d.Image -split '\\')[-1] + '  [' + $d.User + ', ' + $d.IntegrityLevel + ']' } 3 { 'kết nối mạng    ' + ($d.Image -split '\\')[-1] + ' -> ' + $d.DestinationIp + ':' + $d.DestinationPort } 8 { 'CreateRemoteThread ' + ($d.SourceImage -split '\\')[-1] + ' -> ' + ($d.TargetImage -split '\\')[-1] } 10 { 'mở tiến trình   ' + ($d.SourceImage -split '\\')[-1] + ' -> ' + ($d.TargetImage -split '\\')[-1] + ' quyền ' + $d.GrantedAccess } }) }
@ps Get-WinEventMau sm/powercat-1-3.evtx -Oldest | ForEach-Object { $d = @{}; ([xml]$_.ToXml()).Event.EventData.Data | ForEach-Object { $d[$_.Name] = $_.'#text' }; '{0}  {1,-2} {2}' -f $d.UtcTime.Substring(11, 8), $_.Id, $(switch ($_.Id) { 1 { ($d.ParentImage -split '\\')[-1] + ' -> ' + $d.CommandLine } 3 { ($d.Image -split '\\')[-1] + '  ' + $d.SourceIp + ':' + $d.SourcePort + ' -> ' + $d.DestinationIp + ':' + $d.DestinationPort + ' ' + $d.Protocol + ' Initiated=' + $d.Initiated } 10 { ($d.SourceImage -split '\\')[-1] + ' mở ' + ($d.TargetImage -split '\\')[-1] + ' ' + $d.GrantedAccess } }) }
@ps Get-WinEventMau sm/lsass-mimikatz-10.evtx, sm/mimikatz-github-3-10.evtx | ForEach-Object { $d = @{}; ([xml]$_.ToXml()).Event.EventData.Data | ForEach-Object { $d[$_.Name] = $_.'#text' }; [pscustomobject]@{ Id = $_.Id; Nguon = ($d.SourceImage + $d.Image -split '\\')[-1]; Dich = if ($_.Id -eq 10) { ($d.TargetImage -split '\\')[-1] } else { $d.DestinationIp + ':' + $d.DestinationPort }; Quyen = $d.GrantedAccess; CallTrace = if ($d.CallTrace) { ($d.CallTrace -split '\|' | ForEach-Object { ($_ -split '\\')[-1] }) -join ' | ' } } } | Format-List
@ps Get-WinEventMau sm/psinject-7-8-10.evtx | Group-Object Id | ForEach-Object { $d = @{}; ([xml]$_.Group[0].ToXml()).Event.EventData.Data | ForEach-Object { $d[$_.Name] = $_.'#text' }; '{0,2} × {1}  {2}' -f $_.Count, $_.Name, $(switch ([int]$_.Name) { 7 { ($d.Image -split '\\')[-1] + ' nạp ' + ($d.ImageLoaded -split '\\')[-1] } 8 { ($d.SourceImage -split '\\')[-1] + ' -> ' + ($d.TargetImage -split '\\')[-1] + ' (CreateRemoteThread)' } 10 { '? -> ' + ($d.TargetImage -split '\\')[-1] + ' quyền ' + $d.GrantedAccess } }) }
@ps Get-WinEventMau sm/firefox-comhijack-11-13-7-1.evtx -Oldest | Where-Object { $_.Id -in 11, 13 } | ForEach-Object { $d = @{}; ([xml]$_.ToXml()).Event.EventData.Data | ForEach-Object { $d[$_.Name] = $_.'#text' }; '{0} {1,-14} {2}{3}' -f $_.Id, ($d.Image -split '\\')[-1], $(if ($_.Id -eq 11) { $d.TargetFilename } else { ($d.TargetObject -replace '^HKU\\S-1-5-21-[\d-]+_CLASSES', 'HKCU\Software\Classes') }), $(if ($d.Details) { ' = ' + $d.Details }) }
@ps Get-WinEventMau tc/runkey-sysmon13.evtx | ForEach-Object { ([xml]$_.ToXml()).Event.EventData.Data | Where-Object Name -in 'EventType', 'Image', 'TargetObject', 'Details' | Format-Table Name, '#text' -AutoSize -Wrap }
@ps (Get-WinEventMau (Get-ChildItem mau/*.evtx, tc/*.evtx, sm/*.evtx).FullName -FilterHashtable @{ Id = 22; ProviderName = 'Microsoft-Windows-Sysmon' } 2>$null | Measure-Object).Count
@ps Get-WinEventMau sm/sysmon-unload.evtx | Format-List TimeCreated, LogName, ProviderName, Id, @{n='DeviceName'; e={ $_.Properties[4].Value }}, MachineName
